// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;

    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        bool okView;
        int256 viewPrice;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 p) {
            okView = true;
            viewPrice = p;
        } catch {
            okView = false;
            viewPrice = 0;
        }

        bool okCallback;
        try c.assertionDisputedCallback(bytes32(0)) {
            okCallback = true;
        } catch {
            okCallback = false;
        }

        if (okView && time != 0) {
            assertTrue(viewPrice != int256(time));
        } else {
            assertTrue(okCallback);
        }
    }
}
